function icon(name,size=18){return `<svg aria-hidden="true" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${ICONS[name]||ICONS.zap}</svg>`;}
const E=(v)=>esc(v==null?'':String(v));
const A=(v)=>E(v).replace(/`/g,'&#96;');
const prefsDefault={id:'preferences',name:'',responseLanguage:'ar-EG',timezone:'Africa/Cairo',currency:'EGP',tts:true,notifications:false,cloudURL:'',cloudAnonKey:'',aiEndpoint:'',syncMode:'Local'};
let state={wake:{enabled:false,onDeviceAvailable:false,error:"",microphoneGranted:false},chatGPT:{status:'not_connected',connected:false,email:'',error:''},page:'overview',data:Object.fromEntries(COLLECTIONS.map(k=>[k,[]])),prefs:{...prefsDefault},taskFilter:'All',query:'',calMonth:new Date(),calDate:today(),calView:'Month',projectId:null,investmentTab:'Watchlist',businessProject:'',goalTab:'Goals',mobileMore:false,modal:null,voiceState:'idle',busy:false,online:navigator.onLine,toast:null};
let voiceRecognition=null,toastTimer=null,autoTimer=null,autoRunning=false;
const root=document.getElementById('app');

function collection(kind){return state.data[kind]||[];}
function byId(kind,id){return collection(kind).find(x=>x.id===id);}
function projectName(id){return byId('projects',id)?.title||'Unassigned';}
function displayCurrency(){return state.prefs.currency||'EGP';}
function rowsSorted(kind,key='createdAt'){return [...collection(kind)].sort((a,b)=>String(b[key]||'').localeCompare(String(a[key]||'')));}
function openTasks(){return collection('tasks').filter(t=>t.status!=='Done');}
function dueTasks(){return openTasks().filter(t=>t.due===today());}
function overdueTasks(){return openTasks().filter(t=>t.due&&t.due<today());}
function eventDay(ev){return (ev.startsAt||'').slice(0,10);}
function upcomingEvents(){return [...collection('events')].filter(x=>(x.startsAt||'').slice(0,10)>=today()).sort((a,b)=>a.startsAt.localeCompare(b.startsAt));}
function tag(txt,kind=''){return `<span class="status-tag ${E(kind||String(txt).toLowerCase().replace(/\s+/g,'-'))}">${E(txt)}</span>`;}
function empty(title,body,ic='layers',button=''){return `<div class="empty"><div class="empty-symbol">${icon(ic,25)}</div><strong>${E(title)}</strong><span>${E(body)}</span>${button}</div>`;}
function actionBtn(action,title,ic='plus',cls='outline',extras=''){return `<button type="button" class="btn ${cls}" data-action="${A(action)}" ${extras}>${icon(ic,15)} ${E(title)}</button>`;}
function header(kicker,title,desc,action=''){return `<div class="page-header"><div><div class="eyebrow">${E(kicker)}</div><h1>${E(title)}</h1><p>${E(desc)}</p></div><div class="header-actions">${action}</div></div>`;}
function recordActions(kind,item,{other=''}={}){return `<div class="record-actions">${other}<button class="btn sm subtle" data-action="edit" data-kind="${A(kind)}" data-id="${A(item.id)}">${icon('edit',13)} Edit</button><button class="btn sm subtle" data-action="delete" data-kind="${A(kind)}" data-id="${A(item.id)}" aria-label="Delete ${A(item.title||item.name||'record')}">${icon('trash',13)}</button></div>`;}
function wakeStatus(){
 if(!globalThis.RaadAndroid?.getWakeStatus)return {enabled:false,onDeviceAvailable:false,error:'Android APK required.',microphoneGranted:false};
 try{return JSON.parse(globalThis.RaadAndroid.getWakeStatus());}catch{return {enabled:false,error:'Wake Mode status unavailable.'};}
}
function wakeControls(){
 const w=state.wake||{};
 if(!globalThis.RaadAndroid)return `<p class="tiny">Wake Mode requires Android; browser voice is push-to-talk only.</p>`;
 return `<div class="wake-card"><div class="rowline"><div><strong class="wake-name">Wake Mode · “Ya Raad”</strong><p class="tiny">${w.enabled?'5-minute microphone session active · Android may pause recognition when locked':w.onDeviceAvailable?'Experimental 5-minute screen-off listening · opt-in':'Speech recognizer unavailable on this phone'}</p></div>${tag(w.enabled?'Listening':'Off',w.enabled?'active':'paused')}</div><div class="header-actions" style="margin-top:12px">${w.enabled?actionBtn('wake-stop','Stop Wake Mode','mic-off','outline'):actionBtn('wake-start','Enable Wake Mode','mic','outline',w.onDeviceAvailable?'':'disabled')} ${actionBtn('wake-refresh','Check status','repeat','subtle')}</div><p class="tiny" style="margin-top:10px">On-device recognition only. Mic notification while active. Some devices cannot listen through lock screen. Unlock RAAD to review actions; messages never send automatically.</p>${w.error?`<p class="gpt-error">${E(w.error)}</p>`:''}</div>`;
}
async function executeActionWithApproval(action){
 const validated=checkDeviceAction(action.type,action);
 if(!globalThis.RaadAndroid?.performDeviceAction)throw Error('Device actions require Android APK.');
 const label=describeAction(validated);
 if(!confirm(`RAAD wants to prepare this Android action. Review before proceeding:\n\n${label}\n\nThe target app still requires your final confirmation.`))return false;
 globalThis.RaadAndroid.performDeviceAction(JSON.stringify(validated));return true;
}
async function consumeWakeCommand(){
 if(!globalThis.RaadAndroid?.takePendingVoiceCommand||state.busy)return;
 let command='';try{command=globalThis.RaadAndroid.takePendingVoiceCommand()||'';}catch{return;}
 if(command){state.page='assistant';refresh();await doAssistant(command);}
}
function stateBadge(){return state.chatGPT.connected?tag('ChatGPT Plan Connected','active'):state.prefs.aiEndpoint&&cloudConnected()?tag('Custom AI Configured','active'):tag('AI Not Connected','paused');}
function metric(title,value,detail,ic='activity',color=''){return `<div class="panel metric"><div class="overline"><span>${E(title)}</span>${icon(ic,18)}</div><div class="number ${E(color)}">${E(value)}</div><div class="details">${E(detail)}</div></div>`;}

function renderShell(){
 const current=NAV.find(([id])=>id===state.page)?.[1]||'Overview';
 root.innerHTML=`<div class="app-shell raadv2 ${state.online?'':'offline'}"><aside class="sidebar"><div class="brand"><div class="brand-mark"><svg viewBox='0 0 48 48' width='30' height='30' fill='none' aria-hidden='true'><path d='M12 38V10h15c12 0 12 16 0 16H12m15-1 10 13' stroke='currentColor' stroke-width='4.5' stroke-linecap='round' stroke-linejoin='round'/><path d='M32 9h7m-3.5-3.5v7' stroke='#6ef2fd' stroke-width='1.5'/></svg></div><div><div class="brand-title">RAAD<span style="color:var(--cyan)">.</span></div><div class="brand-caption">PERSONAL INTELLIGENCE OS</div></div></div><div class="side-group"><div class="side-label">YOUR COMMAND CENTER</div>${NAV.slice(0,5).map(navButton).join('')}<div class="side-label">YOUR WORKSPACES</div>${NAV.slice(5,10).map(navButton).join('')}<div class="side-label">SYSTEM</div>${NAV.slice(10).map(navButton).join('')}</div><div class="sidebar-footer"><div class="rowline"><strong style="font-size:12px">SYSTEM STATUS</strong>${icon(state.online?'wifi':'wifi-off',15)}</div><p class="tiny"><span class="online-dot"></span>${state.online?'Browser online':'Device offline'} · Local storage active</p><p class="tiny" style="margin-bottom:0">LOCAL-FIRST / NO API KEY</p></div></aside><div class="main-area"><header class="topbar"><div><div class="eyebrow">RAAD AI / ${E(current.toUpperCase())}</div><div class="top-date">${E(new Date().toLocaleDateString('en-US',{weekday:'long',day:'numeric',month:'long',year:'numeric',timeZone:'Africa/Cairo'}))} · Cairo time</div></div><div class="top-right"><span class="pill neutral hide-mobile">${icon('shield-check',13)} LOCAL FIRST</span><span class="pill ${state.online?'':'warn'}">${icon(state.online?'wifi':'wifi-off',13)} ${state.online?'ONLINE':'OFFLINE'}</span><button class="icon-btn" data-page="settings" title="Settings">${icon('settings',18)}</button></div></header><main id="view" class="page">${renderPage()}</main></div></div><nav class="mobile-bottom" aria-label="Primary navigation">${[['overview','Home','layout-dashboard'],['tasks','Tasks','list-todo'],['assistant','RAAD','zap'],['projects','Projects','layers']].map(([p,n,i])=>`<button data-page="${p}" class="${state.page===p?'active':''} ${p==='assistant'?'center':''}">${icon(i,p==='assistant'?23:21)}<span>${n}</span></button>`).join('')}<button data-action="mobile-more" class="${!PRIMARY.includes(state.page)?'active':''}">${icon('menu',21)}<span>More</span></button></nav>${state.mobileMore?`<div class="mobile-more" data-action="close-more"><div class="more-sheet">${NAV.filter(([p])=>!PRIMARY.includes(p)).map(navButton).join('')}</div></div>`:''}<div id="modal-root">${state.modal?renderModal():''}</div><div class="toast-holder" aria-live="polite" id="toasts"></div>`;
 const log=document.getElementById('chat-log');if(log)log.scrollTop=log.scrollHeight;
}
function navButton([p,n,i]){return `<button class="nav-btn ${state.page===p?'active':''}" data-page="${p}">${icon(i,18)}<span>${E(n)}</span></button>`;}
function renderPage(){switch(state.page){case'overview':return overview();case'assistant':return assistant();case'tasks':return tasksPage();case'calendar':return calendarPage();case'projects':return projectsPage();case'business':return businessPage();case'income':return incomePage();case'investments':return investmentsPage();case'automations':return automationsPage();case'goals':return goalsPage();case'settings':return settingsPage();default:return overview();}}
function refresh(){renderShell();}
function setPage(p){if(!NAV.some(([id])=>id===p))return;state.page=p;state.query='';state.mobileMore=false;state.modal=null;refresh();window.scrollTo({top:0,behavior:'instant'});}
function showToast(message,error=false){clearTimeout(toastTimer);const box=document.getElementById('toasts');if(!box)return;box.innerHTML=`<div class="toast ${error?'error':''}">${E(message)}</div>`;toastTimer=setTimeout(()=>{if(box)box.innerHTML='';},4200);}
function renderRecords(kind,makeCard,filter=null){const allRecords=rowsSorted(kind).filter(x=>!filter||filter(x)).filter(x=>!state.query||JSON.stringify(x).toLowerCase().includes(state.query.toLowerCase()));return allRecords.length?`<div class="record-grid">${allRecords.map(makeCard).join('')}</div>`:empty('Nothing here yet','Create your first record to start tracking it.',kind==='tasks'?'list-todo':'layers');}
function searchTools(kind,filters=''){return `<div class="search-row"><input class="search" type="search" id="global-search" placeholder="Search your records..." aria-label="Search records" value="${A(state.query)}"/><div id="filter-slot">${filters}</div>${actionBtn('new','Add new','plus','primary',`data-kind="${A(kind)}"`)}</div>`;}
function introAction(kind,text='New'){return actionBtn('new',text,'plus','primary',`data-kind="${A(kind)}"`);}

function overview(){
 const t=dueTasks(),late=overdueTasks(),activeProjects=collection('projects').filter(p=>p.status!=='Completed'),events=upcomingEvents();
 const upcoming=[...events.map(e=>({...e,_type:'Event',_date:e.startsAt})),...openTasks().filter(t=>t.due).map(t=>({...t,_type:'Task',_date:t.due+'T12:00'}))].sort((a,b)=>a._date.localeCompare(b._date)).slice(0,6);
 const logs=rowsSorted('business');const currency=displayCurrency();const revenue=sum(logs.filter(x=>x.type==='Revenue'&&x.currency===currency),'amount');const expenses=sum(logs.filter(x=>x.type==='Expense'&&x.currency===currency),'amount');
 const greeting=new Date().getHours()<12?'Good morning':new Date().getHours()<18?'Good afternoon':'Good evening';
 return `<div class="overview-version"><span class="system-live"></span> RAAD OS / V4.0 <span class="version-line"></span> DESIGNED FOR CLARITY</div>${header('MISSION CONTROL',`${greeting}${state.prefs.name?', '+state.prefs.name:''}.`,'A clear view of your day, your projects, and your next move.',actionBtn('go-assistant','Talk to RAAD','sparkles','primary'))}
  <section class="intelligence-hero"><div class="hero-copy"><div class="hero-eyebrow"><span class="hero-blink"></span> YOUR PERSONAL COMMAND SYSTEM</div><h2>Clarity, at the speed<br/>of <em>thought.</em></h2><p>One intelligence layer for your priorities, business, projects, and decisions. Grounded in your real records.</p><div class="hero-actions"><button class="btn primary" data-page="assistant">${icon('sparkles',16)} Open RAAD Core</button><span class="hero-status">${state.chatGPT.connected?'ChatGPT plan active':'ChatGPT plan not connected'}</span></div></div><div class="hero-orb" aria-hidden="true"><span class="orbit orbit-a"></span><span class="orbit orbit-b"></span><span class="orbit orbit-c"></span><span class="hero-orb-center"><span>R</span></span></div></section>
  <div class="grid metrics">${metric('Tasks due today',t.length,`${late.length} overdue items`,'list-todo','blue')}${metric('Active projects',activeProjects.length,`${collection('projects').length} projects in total`,'layers')}${metric('Upcoming events',events.length,'Scheduled today and ahead','calendar-days')}${metric('Tracked net',money(revenue-expenses,currency),`Recorded entries only · ${currency}`,'wallet',revenue>=expenses?'green':'amber')}</div>
 <div class="grid two"><section class="panel"><div class="panel-heading"><div><h2 class="panel-title">Your priority queue</h2><p class="panel-desc">Tasks that need attention now</p></div><button class="btn sm subtle" data-page="tasks">All tasks ${icon('arrow-right',13)}</button></div>${openTasks().sort((a,b)=>(a.due||'9999').localeCompare(b.due||'9999')).slice(0,5).map(taskRow).join('')||empty('All clear','Your task list is empty. Add your first priority.','check-circle',introAction('tasks','Create task'))}</section><section class="panel"><div class="panel-heading"><div><h2 class="panel-title">Upcoming timeline</h2><p class="panel-desc">Your next calendar events and deadlines</p></div><button class="btn sm subtle" data-page="calendar">Calendar ${icon('arrow-right',13)}</button></div><div class="flowlist">${upcoming.map(x=>`<div class="list-row"><div style="color:${x._type==='Event'?'var(--cyan)':'var(--amber)'}">${icon(x._type==='Event'?'calendar-days':'clock',17)}</div><div class="grow"><div class="item-title">${E(x.title)}</div><div class="item-meta">${x._type==='Event'?dateTimeLabel(x.startsAt):dateLabel(x.due)} · ${E(x._type)}</div></div></div>`).join('')||empty('No upcoming items','Events and dated tasks appear here.','calendar-days')}</div></section></div>
 <div class="grid half section-space"><section class="panel"><div class="panel-heading"><h2 class="panel-title">Project pulse</h2><button class="btn sm subtle" data-page="projects">Open workspace ${icon('arrow-right',13)}</button></div>${activeProjects.slice(0,4).map(p=>`<div style="margin:15px 0"><div class="rowline"><span style="font-size:13px;font-weight:700">${E(p.title)}</span><span class="small muted">${clamp(Number(p.progress)||0,0,100)}%</span></div><div class="progress"><span style="width:${clamp(Number(p.progress)||0,0,100)}%"></span></div></div>`).join('')||empty('No active projects','Create a project to manage your business milestones.','layers')}</section><section class="panel"><div class="panel-heading"><h2 class="panel-title">Daily briefing</h2><span class="pill neutral">LOCAL DATA</span></div><div style="font-size:13px;line-height:1.9;color:#c5d6e6">${late.length?`<strong style="color:var(--red)">${late.length} overdue task${late.length!==1?'s':''}</strong> need a new plan.`:'No overdue tasks recorded.'}<br/>${t.length} task${t.length!==1?'s':''} due today. ${events.filter(x=>eventDay(x)===today()).length} calendar event${events.filter(x=>eventDay(x)===today()).length===1?'':'s'} today.<br/>${activeProjects.length} projects currently in progress.</div><div class="divider"></div><div class="rowline"><span class="tiny">Briefing uses only your saved information.</span><button class="btn sm outline" data-page="assistant">Ask RAAD</button></div></section></div>`;
}
function taskRow(x){return `<div class="list-row"><button class="icon-btn" data-action="complete-task" data-id="${A(x.id)}" title="Mark complete" style="width:32px;height:32px;color:var(--cyan)">${icon('check',17)}</button><div class="grow"><div class="item-title">${E(x.title)}</div><div class="item-meta">${x.due?dateLabel(x.due):'No deadline'}${x.projectId?' · '+E(projectName(x.projectId)):''}</div></div>${tag(x.due&&x.due<today()?'Overdue':x.priority||'Medium',x.due&&x.due<today()?'overdue':(x.priority||'Medium').toLowerCase())}<button class="icon-btn" data-action="edit" data-kind="tasks" data-id="${A(x.id)}" title="Edit task">${icon('edit',15)}</button></div>`;}
function tasksPage(){const tasks=[...collection('tasks')].sort((a,b)=>Number(a.status==='Done')-Number(b.status==='Done')||(a.due||'9999').localeCompare(b.due||'9999'));const filtered=tasks.filter(x=>state.taskFilter==='All'||(state.taskFilter==='Overdue'?x.status!=='Done'&&x.due&&x.due<today():x.status===state.taskFilter)).filter(x=>!state.query||JSON.stringify(x).toLowerCase().includes(state.query.toLowerCase()));return `${header('PERSONAL PRODUCTIVITY','Tasks','Keep important work moving, one action at a time.',introAction('tasks','Create task'))}<div class="grid metrics">${metric('Open',openTasks().length,'Tasks awaiting completion','list-todo')}${metric('Due today',dueTasks().length,'Deadline is today','clock','blue')}${metric('Overdue',overdueTasks().length,'Needs your attention','circle-alert','amber')}${metric('Completed',collection('tasks').filter(t=>t.status==='Done').length,'Tasks finished','check-circle','green')}</div><section class="panel"><div class="search-row"><input class="search" type="search" id="global-search" placeholder="Search tasks..." value="${A(state.query)}" aria-label="Search tasks"/><select class="select" data-filter="taskFilter" aria-label="Task status">${['All','To Do','In Progress','Overdue','Done'].map(x=>`<option ${state.taskFilter===x?'selected':''}>${x}</option>`).join('')}</select></div>${filtered.length?`<div class="flowlist">${filtered.map(x=>`<div class="list-row"><button class="icon-btn" data-action="complete-task" data-id="${A(x.id)}" aria-label="Toggle task completion">${icon(x.status==='Done'?'check-circle':'check',17)}</button><div class="grow"><div class="item-title" style="${x.status==='Done'?'text-decoration:line-through;opacity:.6':''}">${E(x.title)}</div><div class="item-meta">${x.due?dateLabel(x.due):'No deadline'} · ${E(projectName(x.projectId))} ${x.category?' · '+E(x.category):''}</div></div>${tag(x.status==='Done'?'Done':x.priority||'Medium',(x.status==='Done'?'done':x.priority||'Medium').toLowerCase())}<button class="icon-btn" data-action="edit" data-kind="tasks" data-id="${A(x.id)}" title="Edit">${icon('edit',15)}</button><button class="icon-btn" data-action="delete" data-kind="tasks" data-id="${A(x.id)}" title="Delete">${icon('trash',15)}</button></div>`).join('')}</div>`:empty('No tasks match','Adjust the search or create a new task.','list-todo')}</section>`;}
function calendarPage(){const date=new Date(state.calMonth);date.setDate(1);const yyyy=date.getFullYear(),mm=date.getMonth();const first=new Date(yyyy,mm,1),start=new Date(first);start.setDate(start.getDate()-start.getDay());const selected=state.calDate;const calendarEvents=collection('events').filter(e=>eventDay(e)===selected).sort((a,b)=>(a.startsAt||'').localeCompare(b.startsAt||''));const calendarTasks=collection('tasks').filter(t=>t.due===selected);
 const monthly=Array.from({length:42},(_,i)=>{const d=new Date(start);d.setDate(d.getDate()+i);const ds=localISO(d);const matches=collection('events').filter(e=>eventDay(e)===ds);const tasks=collection('tasks').filter(x=>x.due===ds);return `<button class="cal-day ${d.getMonth()!==mm?'outside':''} ${ds===today()?'today':''} ${ds===selected?'selected':''}" data-action="select-date" data-date="${ds}"><span class="day-number">${d.getDate()}</span>${matches.length||tasks.length?`<span class="cal-dot"></span><span class="cal-mini">${E(matches[0]?.title||tasks[0]?.title||'')}</span>`:''}</button>`;}).join('');
 const current=new Date(`${selected}T12:00`);const weekStart=new Date(current);weekStart.setDate(current.getDate()-current.getDay());const weekDays=Array.from({length:7},(_,i)=>{const d=new Date(weekStart);d.setDate(weekStart.getDate()+i);return d;});const visibleDays=state.calView==='Week'?weekDays:[current];
 return `${header('YOUR SCHEDULE','Calendar','Plan your time across events, tasks, and deadlines.',introAction('events','New event'))}<div class="calendar-shell"><section class="panel"><div class="rowline" style="flex-wrap:wrap;margin-bottom:20px"><div class="cal-toolbar"><button class="icon-btn" data-action="cal-prev" aria-label="Previous period">${icon('chevron-left',17)}</button><h2 class="panel-title">${E(state.calView==='Month'?date.toLocaleDateString('en-US',{month:'long',year:'numeric'}):current.toLocaleDateString('en-US',{month:'long',year:'numeric'}))}</h2><button class="icon-btn" data-action="cal-next" aria-label="Next period">${icon('chevron-right',17)}</button><button class="btn sm subtle" data-action="cal-today">Today</button></div><div class="tabs" style="margin:0">${['Month','Week','Day'].map(v=>`<button class="${state.calView===v?'active':''}" data-action="cal-view" data-value="${v}">${v}</button>`).join('')}</div></div>
 ${state.calView==='Month'?`<div class="cal-grid">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(d=>`<div class="cal-head">${d}</div>`).join('')}${monthly}</div>`:`<div class="weekday-list">${visibleDays.map(d=>{const ds=localISO(d);const events=collection('events').filter(x=>eventDay(x)===ds);const tasks=collection('tasks').filter(x=>x.due===ds);return `<button class="weekday-group" style="text-align:left;color:var(--ink);cursor:pointer" data-action="select-date" data-date="${ds}"><strong>${E(d.toLocaleDateString('en-US',{weekday:'long',day:'numeric',month:'short'}))}${ds===today()?' · Today':''}</strong><p class="small muted">${events.length} events · ${tasks.length} tasks</p>${events.map(e=>`<div class="small">${icon('calendar-days',13)} ${E(e.title)} · ${E((e.startsAt||'').slice(11,16))}</div>`).join('')}</button>`;}).join('')}</div>`}
 <p class="tiny" style="margin:16px 0 0">Times are entered in your device's timezone. Default preference: Africa/Cairo.</p></section><section class="panel"><div class="panel-heading"><div><h2 class="panel-title">${dateLabel(selected)}</h2><p class="panel-desc">Selected agenda</p></div></div>${calendarEvents.length||calendarTasks.length?`<div class="flowlist">${calendarEvents.map(e=>`<div class="list-row"><div style="color:var(--cyan)">${icon('calendar-days',18)}</div><div class="grow"><div class="item-title">${E(e.title)}</div><div class="item-meta">${dateTimeLabel(e.startsAt)}</div></div><button class="icon-btn" data-action="edit" data-kind="events" data-id="${A(e.id)}" aria-label="Edit event">${icon('edit',15)}</button></div>`).join('')}${calendarTasks.map(t=>`<div class="list-row"><div style="color:var(--amber)">${icon('list-todo',18)}</div><div class="grow"><div class="item-title">${E(t.title)}</div><div class="item-meta">Task · ${E(t.priority||'Medium')}</div></div><button class="icon-btn" data-action="edit" data-kind="tasks" data-id="${A(t.id)}" aria-label="Edit task">${icon('edit',15)}</button></div>`).join('')}</div>`:empty('Nothing scheduled','Add an event or assign a due date to a task.','calendar-days',introAction('events','Add event'))}</section></div>`;
}
function projectsPage(){const projects=rowsSorted('projects');const selected=state.projectId?byId('projects',state.projectId):null;return `${header('WORKSPACE','Projects','Every project has its own tasks, deadlines, progress and business records.',introAction('projects','New project'))}${selected?projectDetails(selected):`<div class="grid metrics">${metric('All projects',projects.length,'Across your workspaces','layers')}${metric('Active',projects.filter(x=>x.status==='Active').length,'Currently in progress','activity')}${metric('Completed',projects.filter(x=>x.status==='Completed').length,'Delivered projects','check-circle','green')}${metric('Upcoming deadlines',projects.filter(x=>x.deadline&&x.deadline>=today()).length,'Deadlines on file','clock','blue')}</div>${projects.length?`<div class="record-grid">${projects.map(p=>{const tasks=collection('tasks').filter(x=>x.projectId===p.id);return `<article class="panel record-card"><div class="rowline">${tag(p.status||'Planned',(p.status||'Planned').toLowerCase())}<span class="muted small">${E(p.category||'Project')}</span></div><h3 class="record-title">${E(p.title)}</h3><div class="record-desc">${E(p.description||'No description added.')}</div><div class="rowline"><span class="small muted">Progress</span><strong class="small">${clamp(Number(p.progress)||0,0,100)}%</strong></div><div class="progress"><span style="width:${clamp(Number(p.progress)||0,0,100)}%"></span></div><div class="record-meta">${icon('list-todo',14)} ${tasks.length} tasks · ${p.deadline?dateLabel(p.deadline):'No deadline'}</div>${recordActions('projects',p,{other:`<button class="btn sm outline" data-action="project-open" data-id="${A(p.id)}">Open workspace ${icon('arrow-right',13)}</button>`})}</article>`;}).join('')}</div>`:empty('Build your first workspace','Keep projects, deliverables, and finances organized in one place.','layers',introAction('projects','Create project'))}`}`;}
function projectDetails(p){const tasks=collection('tasks').filter(x=>x.projectId===p.id);const milestones=collection('milestones').filter(x=>x.projectId===p.id);const ledger=collection('business').filter(x=>x.projectId===p.id);const clients=collection('clients').filter(x=>x.projectId===p.id);const revenue=sum(ledger.filter(x=>x.type==='Revenue'&&x.currency===displayCurrency()),'amount');const costs=sum(ledger.filter(x=>x.type==='Expense'&&x.currency===displayCurrency()),'amount');return `<div style="margin-bottom:17px"><button class="btn sm outline" data-action="project-back">${icon('chevron-left',14)} All projects</button></div><div class="panel" style="margin-bottom:20px"><div class="rowline" style="align-items:flex-start"><div><div class="eyebrow">PROJECT WORKSPACE</div><h2 style="font:600 28px 'Space Grotesk';margin:9px 0">${E(p.title)}</h2><p class="muted small">${E(p.description||'No project description recorded.')}</p></div>${tag(p.status||'Planned')}</div><div class="rowline small"><span>Overall progress</span><strong>${clamp(Number(p.progress)||0,0,100)}%</strong></div><div class="progress"><span style="width:${clamp(Number(p.progress)||0,0,100)}%"></span></div><div class="rowline" style="margin-top:14px;flex-wrap:wrap"><span class="small muted">Deadline: ${p.deadline?dateLabel(p.deadline):'Unscheduled'}</span><button class="btn sm subtle" data-action="edit" data-kind="projects" data-id="${A(p.id)}">${icon('edit',14)} Edit project</button></div></div><div class="grid metrics">${metric('Pending tasks',tasks.filter(x=>x.status!=='Done').length,`${tasks.length} total`,'list-todo')}${metric('Milestones',milestones.filter(x=>x.status==='Done').length,`${milestones.length} recorded`,'check-circle')}${metric('Revenue',money(revenue,displayCurrency()),'Recorded project revenue','wallet','green')}${metric('Net',money(revenue-costs,displayCurrency()),'Same-currency records only','activity',revenue>=costs?'green':'amber')}</div><div class="grid half"><section class="panel"><div class="panel-heading"><h3 class="panel-title">Project tasks</h3><button class="btn sm outline" data-action="new" data-kind="tasks" data-project="${A(p.id)}">${icon('plus',14)} Add task</button></div>${tasks.map(taskRow).join('')||empty('No tasks yet','Create a task associated with this project.','list-todo')}</section><section class="panel"><div class="panel-heading"><h3 class="panel-title">Milestones</h3><button class="btn sm outline" data-action="new" data-kind="milestones" data-project="${A(p.id)}">${icon('plus',14)} Add milestone</button></div>${milestones.map(x=>`<div class="list-row"><div class="grow"><div class="item-title">${E(x.title)}</div><div class="item-meta">${x.due?dateLabel(x.due):'No deadline'} · ${E(x.status||'Planned')}</div></div><button class="icon-btn" data-action="edit" data-kind="milestones" data-id="${A(x.id)}" aria-label="Edit milestone">${icon('edit',14)}</button></div>`).join('')||empty('No milestones','Define your key project deliverables.','target')}</section></div><div class="grid half section-space"><section class="panel"><div class="panel-heading"><h3 class="panel-title">Business entries</h3><button class="btn sm outline" data-action="new" data-kind="business" data-project="${A(p.id)}">${icon('plus',14)} Add record</button></div>${ledger.slice(0,7).map(x=>`<div class="list-row"><div class="grow"><div class="item-title">${E(x.title)}</div><div class="item-meta">${E(x.type)} · ${dateLabel(x.date)}</div></div><strong class="small ${x.type==='Revenue'?'money-positive':'money-negative'}">${money(x.amount,x.currency||'EGP')}</strong></div>`).join('')||empty('No transactions','Add actual revenue and costs for accurate totals.','wallet')}</section><section class="panel"><div class="panel-heading"><h3 class="panel-title">Clients</h3><button class="btn sm outline" data-action="new" data-kind="clients" data-project="${A(p.id)}">${icon('plus',14)} Add client</button></div>${clients.map(x=>`<div class="list-row"><div class="grow"><div class="item-title">${E(x.title)}</div><div class="item-meta">${E(x.email||x.phone||'No contact details')}</div></div><button class="icon-btn" data-action="edit" data-kind="clients" data-id="${A(x.id)}" aria-label="Edit client">${icon('edit',14)}</button></div>`).join('')||empty('No clients','Organize contacts by project.','briefcase-business')}</section></div>`;}
function businessPage(){const records=rowsSorted('business'),cur=displayCurrency(),project=state.businessProject;const scoped=records.filter(x=>!project||x.projectId===project);const revenue=sum(scoped.filter(x=>x.type==='Revenue'&&x.currency===cur),'amount'),cost=sum(scoped.filter(x=>x.type==='Expense'&&x.currency===cur),'amount');const mixed=[...new Set(scoped.map(x=>x.currency).filter(x=>x&&x!==cur))];return `${header('BUSINESS OPERATIONS','Business ledger','Track real revenue, expenses, clients and profitability by project.',introAction('business','New entry'))}<div class="search-row"><select class="select" data-filter="businessProject" aria-label="Filter by project"><option value="">All projects</option>${collection('projects').map(p=>`<option value="${A(p.id)}" ${project===p.id?'selected':''}>${E(p.title)}</option>`).join('')}</select><span class="tiny">Totals in ${E(cur)} only · No automatic FX conversion</span></div><div class="grid metrics">${metric('Revenue',money(revenue,cur),`${scoped.filter(x=>x.type==='Revenue'&&x.currency===cur).length} entries`,'trending-up','green')}${metric('Expenses',money(cost,cur),'Actual recorded expense entries','wallet','amber')}${metric('Net profit / loss',money(revenue-cost,cur),'Revenue minus expenses','activity',revenue>=cost?'green':'amber')}${metric('Clients',collection('clients').filter(x=>!project||x.projectId===project).length,'Saved business contacts','briefcase-business')}</div>${mixed.length?`<div class="alert-banner info">${icon('circle-alert',18)} Entries in ${E(mixed.join(', '))} are omitted from these ${E(cur)} totals. Change the display currency in Settings to view those totals.</div>`:''}<div class="grid two"><section class="panel"><div class="panel-heading"><h2 class="panel-title">Revenue & expenses</h2><span class="pill neutral">MANUAL RECORDS</span></div>${scoped.length?`<div class="flowlist">${scoped.map(x=>`<div class="list-row"><div class="grow"><div class="item-title">${E(x.title)}</div><div class="item-meta">${dateLabel(x.date)} · ${E(projectName(x.projectId))} · ${E(x.type)}</div></div><strong class="small ${x.type==='Revenue'?'money-positive':'money-negative'}">${x.type==='Revenue'?'+':'−'}${money(x.amount,x.currency||cur)}</strong><button class="icon-btn" data-action="edit" data-kind="business" data-id="${A(x.id)}" aria-label="Edit ledger record">${icon('edit',14)}</button><button class="icon-btn" data-action="delete" data-kind="business" data-id="${A(x.id)}" aria-label="Delete ledger record">${icon('trash',14)}</button></div>`).join('')}</div>`:empty('No financial records','Add a real revenue or expense record to see your totals.','wallet')}</section><section class="panel"><div class="panel-heading"><h2 class="panel-title">Clients</h2><button class="btn sm outline" data-action="new" data-kind="clients">${icon('plus',14)} Add client</button></div>${collection('clients').filter(x=>!project||x.projectId===project).map(x=>`<div class="list-row"><div class="grow"><div class="item-title">${E(x.title)}</div><div class="item-meta">${E(x.email||x.phone||'No contact details')} · ${E(projectName(x.projectId))}</div></div><button class="icon-btn" data-action="edit" data-kind="clients" data-id="${A(x.id)}" aria-label="Edit client">${icon('edit',14)}</button><button class="icon-btn" data-action="delete" data-kind="clients" data-id="${A(x.id)}" aria-label="Delete client">${icon('trash',14)}</button></div>`).join('')||empty('No clients yet','Save your client contacts with a project association.','briefcase-business')}</section></div>`;}
function incomePage(){const list=rowsSorted('opportunities').filter(x=>!state.query||JSON.stringify(x).toLowerCase().includes(state.query.toLowerCase()));return `${header('GROWTH ENGINE','Income Opportunities','Validate low-cost business ideas before putting money behind them.',introAction('opportunities','New opportunity'))}<div class="alert-banner info">${icon('shield-check',18)} Research is user-entered unless a real research integration is connected. Financial scenarios are estimates, not guarantees.</div><div class="search-row"><input id="global-search" class="search" type="search" placeholder="Search opportunities..." value="${A(state.query)}" aria-label="Search opportunities"/></div>${list.length?`<div class="record-grid">${list.map(o=>`<article class="panel record-card"><div class="rowline">${tag(o.status||'Researching')}${tag(o.verified==='Yes'?'User-marked verified':'Unverified',o.verified==='Yes'?'verified':'paused')}</div><h3 class="record-title">${E(o.title)}</h3><div class="record-desc">${E(o.description||'No description recorded.')}</div><div class="record-meta">${icon('target',14)} ${E(o.customers||'Target customers not set')}</div><div class="rowline small"><span class="muted">Startup cost (estimate)</span><strong>${o.startCost!==''&&o.startCost!=null?money(o.startCost,o.currency||'EGP'):'Not estimated'}</strong></div><div class="rowline small"><span class="muted">Feasibility (self-assessed)</span><strong>${o.score!==''&&o.score!=null?E(o.score)+'/10':'Not scored'}</strong></div>${o.score!==''&&o.score!=null?`<div class="progress"><span style="width:${clamp(Number(o.score)*10,0,100)}%"></span></div>`:''}<div class="tiny">${o.researchDate?'Reviewed '+dateLabel(o.researchDate):'No research date'}${o.source?' · '+E(o.source):''}</div>${recordActions('opportunities',o,{other:`<button class="btn sm outline" data-action="convert-opportunity" data-id="${A(o.id)}">${icon('arrow-right',13)} Create project</button>`})}</article>`).join('')}</div>`:empty('Your opportunity pipeline is empty','Capture an idea, research its risks, and turn it into an actionable project.','trending-up',introAction('opportunities','Add opportunity'))}`;}
function investmentsPage(){const results=investmentSummary(collection('holdings'));const rows=Object.entries(results);const summary=rows.map(([cur,s])=>`${metric(`Recorded cost · ${cur}`,money(s.cost,cur),`${s.priced+s.unpriced} holdings`,'wallet')}${metric(`Priced holdings · ${cur}`,money(s.value,cur),`${s.unpriced} holdings without current price`,'activity',s.unpriced?'':'blue')}`).join('');const tab=state.investmentTab;return `${header('CAPITAL INTELLIGENCE','Investments','Private watchlists and manual portfolio tracking — never fabricated live prices.',introAction(tab==='Watchlist'?'watchlist':'holdings',tab==='Watchlist'?'Add to watchlist':'Add holding'))}<div class="alert-banner info">${icon('shield-check',18)} Market connection: <strong>Not configured.</strong> All price fields are manual. RAAD will not execute trades or transfer money.</div>${rows.length?`<div class="grid metrics">${summary}${metric('Holdings',collection('holdings').length,'Manually tracked assets','chart-no-axes-combined')}${metric('Watchlist',collection('watchlist').length,'Assets you follow','target')}</div>`:`<div class="grid metrics">${metric('Portfolio holdings',collection('holdings').length,'No price feed connected','wallet')}${metric('Watchlist assets',collection('watchlist').length,'Manual records only','target')}${metric('Market provider','None','No live prices available','wifi-off')}${metric('Trade execution','Disabled','Read-only tracking','shield-check')}</div>`}<div class="tabs">${['Watchlist','Portfolio'].map(t=>`<button data-action="investment-tab" data-value="${t}" class="${tab===t?'active':''}">${t}</button>`).join('')}</div>${tab==='Watchlist'?`<div class="record-grid">${rowsSorted('watchlist').map(w=>`<article class="panel record-card"><div class="rowline">${tag(w.market||'Market')}${tag('Manual Data','paused')}</div><h3 class="record-title">${E(w.symbol||w.title)}</h3><div class="record-desc">${E(w.title||w.description||'Watchlist asset')}</div><div class="record-meta">${icon('target',14)} Target: ${w.targetPrice!==''&&w.targetPrice!=null?money(w.targetPrice,w.currency||'EGP'):'Not set'}</div><div class="record-desc">${E(w.notes||'No notes recorded.')}</div>${recordActions('watchlist',w)}</article>`).join('')}</div>${collection('watchlist').length?'':empty('No assets on your radar','Add EGX stocks, US shares, ETFs, gold or currency exposures.','target',introAction('watchlist','Add asset'))}`:`<div class="record-grid">${rowsSorted('holdings').map(h=>{const q=Number(h.quantity)||0,cost=q*(Number(h.avgCost)||0);const hasPrice=h.currentPrice!==''&&h.currentPrice!=null;const value=hasPrice?q*Number(h.currentPrice):null;return `<article class="panel record-card"><div class="rowline">${tag(h.market||'Holding')}${tag('Manual Data','paused')}</div><h3 class="record-title">${E(h.symbol||h.title||'Holding')}</h3><div class="record-meta">${E(q)} units · ${E(h.currency||'EGP')} · ${h.purchaseDate?dateLabel(h.purchaseDate):'No purchase date'}</div><div class="rowline small"><span class="muted">Purchase cost</span><strong>${money(cost,h.currency||'EGP')}</strong></div><div class="rowline small"><span class="muted">Recorded market value</span><strong>${value===null?'No price entered':money(value,h.currency||'EGP')}</strong></div>${value===null?'':`<div class="rowline small"><span class="muted">Gain / loss</span><strong class="${value>=cost?'money-positive':'money-negative'}">${money(value-cost,h.currency||'EGP')}</strong></div>`}${recordActions('holdings',h)}</article>`;}).join('')}</div>${collection('holdings').length?'':empty('Start your manual portfolio','Record holdings and your actual purchase prices; no fictional quotes.','wallet',introAction('holdings','Add holding'))}`}`;}
function automationsPage(){const automationList=rowsSorted('automations');const logs=rowsSorted('automationLogs').slice(0,12);return `${header('WORKFLOW CONTROL','Automation Center','Local, permission-aware workflows that run only while RAAD is open.',introAction('automations','Create workflow'))}<div class="alert-banner">${icon('circle-alert',18)} Local schedules execute while the RAAD tab is open. The app cannot guarantee background alerts or wake itself when closed. No external messages are sent.</div><div class="grid metrics">${metric('Workflows',automationList.length,'Configured locally','zap')}${metric('Active',automationList.filter(x=>x.status==='Active').length,'App-open execution only','activity','green')}${metric('Paused',automationList.filter(x=>x.status==='Paused').length,'Not running','pause')}${metric('Executions',collection('automationLogs').length,'Saved local run history','clipboard-list')}</div><div class="grid two"><section class="panel"><div class="panel-heading"><h2 class="panel-title">Your workflows</h2><span class="pill neutral">LOCAL ONLY</span></div>${automationList.length?`<div class="flowlist">${automationList.map(a=>`<div class="list-row" style="align-items:flex-start"><div style="color:var(--cyan);margin-top:3px">${icon('zap',19)}</div><div class="grow"><div class="item-title">${E(a.title)}</div><div class="item-meta">${E(a.trigger||'Daily briefing')} · ${E(a.frequency||'Daily')} · ${E(a.status||'Paused')}</div><div class="item-meta">Next: ${a.status==='Active'&&a.nextRun?dateTimeLabel(a.nextRun):'Not scheduled'}<br/>Last: ${a.lastRun?dateTimeLabel(a.lastRun):'Never'}</div></div><div style="display:flex;gap:5px;flex-wrap:wrap;justify-content:end"><button class="icon-btn" data-action="run-automation" data-id="${A(a.id)}" title="Run now">${icon('play',15)}</button><button class="icon-btn" data-action="toggle-automation" data-id="${A(a.id)}" title="Toggle status">${icon(a.status==='Active'?'pause':'play',15)}</button><button class="icon-btn" data-action="edit" data-kind="automations" data-id="${A(a.id)}" title="Edit workflow">${icon('edit',15)}</button><button class="icon-btn" data-action="delete" data-kind="automations" data-id="${A(a.id)}" title="Delete workflow">${icon('trash',15)}</button></div></div>`).join('')}</div>`:empty('No workflows yet','Create a daily briefing, overdue task scan, or weekly review.','zap',introAction('automations','New workflow'))}</section><section class="panel"><div class="panel-heading"><h2 class="panel-title">Execution history</h2><span class="pill neutral">${logs.length} RECENT</span></div>${logs.length?`<div class="flowlist">${logs.map(l=>`<div class="list-row"><div style="color:var(--green)">${icon('check-circle',17)}</div><div class="grow"><div class="item-title">${E(l.title)}</div><div class="item-meta">${dateTimeLabel(l.createdAt)} · ${E(l.status)}</div><div class="item-meta">${E(l.details||'')}</div></div></div>`).join('')}</div>`:empty('No runs recorded','When workflows execute, their results and errors appear here.','clipboard-list')}</section></div>`;}
function goalsPage(){const tab=state.goalTab;const goals=rowsSorted('goals'),habits=rowsSorted('habits');return `${header('PERSONAL GROWTH','Goals & Habits','Build consistency and measure progress without external services.',introAction(tab==='Goals'?'goals':'habits',tab==='Goals'?'New goal':'New habit'))}<div class="tabs">${['Goals','Habits'].map(t=>`<button data-action="goal-tab" data-value="${t}" class="${tab===t?'active':''}">${t}</button>`).join('')}</div>${tab==='Goals'?`<div class="record-grid">${goals.map(g=>`<article class="panel record-card"><div class="rowline">${tag(g.status||'Active')}<span class="muted small">${g.due?dateLabel(g.due):'No deadline'}</span></div><h3 class="record-title">${E(g.title)}</h3><div class="record-desc">${E(g.description||'No description.')}</div><div class="rowline small"><span>Progress</span><strong>${clamp(Number(g.progress)||0,0,100)}%</strong></div><div class="progress"><span style="width:${clamp(Number(g.progress)||0,0,100)}%"></span></div>${recordActions('goals',g)}</article>`).join('')}</div>${goals.length?'':empty('No goals defined','Define your next objective and track real progress.','target',introAction('goals','Add goal'))}`:`<div class="record-grid">${habits.map(h=>{const logs=collection('checkins').filter(x=>x.habitId===h.id);const checked=logs.some(l=>l.date===today());return `<article class="panel record-card"><div class="rowline">${tag(h.frequency||'Daily')}${tag(checked?'Checked in today':'Not checked today',checked?'done':'paused')}</div><h3 class="record-title">${E(h.title)}</h3><div class="record-desc">${E(h.description||'')}</div><div class="record-meta">${icon('check-circle',14)} ${logs.length} total check-ins</div>${recordActions('habits',h,{other:`<button class="btn sm ${checked?'outline':'primary'}" data-action="habit-checkin" data-id="${A(h.id)}">${icon(checked?'x':'check',13)} ${checked?'Undo check-in':'Check in'}</button>`})}</article>`;}).join('')}</div>${habits.length?'':empty('No habits yet','Build a routine and record each check-in.','target',introAction('habits','New habit'))}`}`;}
function chatGPTToolbar(){const conn=state.chatGPT;
 if(!globalThis.RaadAndroid)return `<div class="gpt-connect-strip"><div class="gpt-led idle"></div><div class="gpt-connect-copy"><strong>ChatGPT Plan • Android only</strong><span>Install the Android APK to connect your ChatGPT account securely.</span></div><button class="btn outline sm" data-action="chatgpt-open">Open ChatGPT</button></div>`;
 if(conn.connected)return `<div class="gpt-connect-strip connected"><div class="gpt-led"></div><div class="gpt-connect-copy"><strong>ChatGPT Plan Connected</strong><span>${E(conn.email||'Authorized account')} · Tokens stay in encrypted Android storage</span></div><button class="btn subtle sm" data-action="chatgpt-disconnect">Disconnect</button></div>`;
 return `<div class="gpt-connect-strip"><div class="gpt-led idle"></div><div class="gpt-connect-copy"><strong>${conn.status==='connecting'?'Connecting your ChatGPT account…':'Use your ChatGPT plan'}</strong><span>Official sign-in, no API key. Requires an eligible plan and consent.</span></div><button class="btn primary sm" data-action="chatgpt-connect" ${conn.status==='connecting'?'disabled':''}>${icon('sparkles',14)} ${conn.status==='connecting'?'Connecting':'Connect ChatGPT'}</button></div>${conn.error?`<p class="gpt-error">${E(conn.error)}</p>`:''}`;
}
function assistant(){const messages=rowsSorted('messages').reverse();const gpt=state.chatGPT.connected;const live=Boolean(gpt||state.prefs.aiEndpoint&&cloudConnected());let status=gpt?'Powered by your ChatGPT plan':live?'Custom AI endpoint configured':'Offline local commands · Live AI disconnected';return `${header('NEURAL INTERFACE','RAAD Intelligence','Your intelligent command layer. Speak naturally in Egyptian Arabic or English.',actionBtn('clear-chat','Clear conversation','trash','outline'))}
<div class="assistant-connection">${chatGPTToolbar()}</div>
<div class="assistant-layout"><section class="panel chat-panel"><div class="chat-header"><div><div class="eyebrow">ENCRYPTED LOCAL HISTORY</div><h2 class="panel-title">Conversation Stream</h2><div class="tiny" style="margin-top:6px">${E(status)}</div></div>${tag(gpt?'ChatGPT Connected':live?'Endpoint configured':'Offline mode',live?'active':'paused')}</div><div class="chat-log" id="chat-log" role="log" aria-live="polite">${messages.length?messages.map(m=>`<div class="msg ${m.role==='user'?'user':''}" dir="${chatDirection(m.text||'')}"><div class="speaker">${m.role==='user'?'YOU':m.mode==='local'?'RAAD · LOCAL':'RAAD'}</div>${E(m.text)}</div>`).join(''):`<div class="chat-empty"><div class="chat-empty-emblem">${icon('sparkles',33)}</div><div class="eyebrow">SYSTEM READY</div><h3>What can I help you with?</h3><p>${gpt?'Ask a question and RAAD will use your approved ChatGPT plan.':'Connect your ChatGPT plan for AI answers, or manage your tasks and projects with offline commands.'}</p><div class="suggestions">${['يا رعد، نظملي يومي','افتح اليوتيوب','شغل أغنية إنت عمري على الساوند كلاود','اعمل سيرش عن أخبار مصر'].map(t=>`<button data-action="chat-suggestion" data-text="${A(t)}">${E(t)}</button>`).join('')}</div></div>`}</div><form class="chat-form" id="chat-form"><label for="message-input" class="sr-only">Message RAAD</label><input class="input" id="message-input" maxlength="4000" autocomplete="off" placeholder="Message RAAD…" ${state.busy?'disabled':''} required/><button class="btn primary" type="submit" ${state.busy?'disabled':''} aria-label="Send message">${icon('send',18)}</button></form>${wakeControls()}<div class="assistant-external-row"><span>Not eligible for plan sharing?</span><button type="button" class="text-link" data-action="chatgpt-external">${icon('external-link',13)} Continue in ChatGPT app</button></div><div class="message-disclosure">${gpt?'Your messages are sent to OpenAI only when you ask RAAD. ChatGPT conversations are not automatically imported.':'All records stay local. Offline commands work without a model.'}</div></section>
<aside class="panel core-panel"><div class="eyebrow" style="padding-top:6px">RAAD · NEURAL CORE</div><div class="core-wrap ${state.voiceState}"><div class="core-aura"></div><div class="core-ring one"></div><div class="core-ring two"></div><div class="core-ring three"></div><div class="core-disc"><div class="core-innermark">R</div></div></div><div class="core-state">${E(state.voiceState==='idle'?'STANDBY':state.voiceState)}</div><p class="core-hint">${state.voiceState==='listening'?'Listening for your message…':state.voiceState==='thinking'?'Processing your request…':state.voiceState==='speaking'?'Speaking…':gpt?'Your intelligence connection is ready.':'Connect your ChatGPT plan to activate neural assistance.'}</p><div class="core-controls"><button class="btn outline" data-action="voice-listen">${icon(state.voiceState==='listening'?'mic-off':'mic',16)} ${state.voiceState==='listening'?'Stop':'Talk to RAAD'}</button><button class="btn subtle" data-action="voice-mute">${icon(state.prefs.tts?'volume-2':'volume-x',16)} ${state.prefs.tts?'Voice on':'Voice off'}</button></div><div class="core-footer"><span class="online-dot"></span> ${gpt?'CHATGPT PLAN CONNECTED':'LOCAL ENGINE ONLINE'} <span>·</span> ${state.prefs.responseLanguage==='en'?'ENGLISH':'EGYPTIAN ARABIC'}</div></aside></div>`;}

function settingsPage(){const p=state.prefs;return `${header('SYSTEM CONFIGURATION','Settings','Your RAAD preferences, privacy and optional integrations.')}<div class="settings-grid"><section class="panel"><div class="panel-heading"><div><h2 class="panel-title">Personal preferences</h2><p class="panel-desc">English UI · Your choice of assistant language</p></div>${icon('settings',20)}</div><form id="preferences-form" class="form-grid"><div class="field full"><label for="pref-name">Display name</label><input class="input" id="pref-name" name="name" maxlength="80" value="${A(p.name||'')}" placeholder="Optional"/></div><div class="field"><label for="pref-language">Assistant conversation</label><select class="select" id="pref-language" name="responseLanguage" style="width:100%"><option value="ar-EG" ${p.responseLanguage==='ar-EG'?'selected':''}>Egyptian Arabic</option><option value="en" ${p.responseLanguage==='en'?'selected':''}>English</option></select></div><div class="field"><label for="pref-currency">Display currency</label><select class="select" id="pref-currency" name="currency" style="width:100%"><option ${p.currency==='EGP'?'selected':''}>EGP</option><option ${p.currency==='USD'?'selected':''}>USD</option></select></div><div class="field full"><label for="pref-timezone">Timezone</label><select class="select" id="pref-timezone" name="timezone" style="width:100%"><option value="Africa/Cairo" ${p.timezone==='Africa/Cairo'?'selected':''}>Africa/Cairo (default)</option><option value="UTC" ${p.timezone==='UTC'?'selected':''}>UTC</option></select></div><label class="toggle-field full"><input type="checkbox" name="tts" ${p.tts?'checked':''}/> Speak assistant responses when browser supports TTS</label><div class="field full"><button class="btn primary" type="submit">Save preferences</button></div></form></section><section class="panel"><div class="panel-heading"><div><h2 class="panel-title">ChatGPT Plan Connection</h2><p class="panel-desc">Official OpenAI sign-in · no API key required</p></div>${icon('brain-circuit',20)}</div>${chatGPTToolbar()}<div class="divider"></div><h3 class="panel-title" style="font-size:14px">Voice & notifications</h3><p class="tiny">Voice uses Android speech recognition and device TTS where supported. Reminders require RAAD to stay open. Experimental microphone Wake Mode can continue while the phone is locked if Android permits.</p>${wakeControls()}<button class="btn outline sm" data-action="notifications">${icon('circle-alert',14)} Request notification permission</button><div class="divider"></div><p class="tiny">ChatGPT plan usage needs an eligible account and your permission. It does not grant RAAD access to ChatGPT conversation history or memories. Disconnect anytime.</p></section><section class="panel"><div class="panel-heading"><div><h2 class="panel-title">Cloud backup (optional)</h2><p class="panel-desc">Supabase · manual upload and restore</p></div>${icon('wifi',20)}</div><div class="alert-banner info">${icon('shield-check',17)} ${cloudConnected()?'Authenticated session active. Choose upload or restore explicitly.':'Cloud disconnected. Local data is not synchronized across devices.'}</div><form id="cloud-settings-form" class="form-grid"><div class="field full"><label for="cloud-url">Supabase project URL</label><input class="input" name="cloudURL" id="cloud-url" type="url" value="${A(p.cloudURL)}" placeholder="https://project.supabase.co"/></div><div class="field full"><label for="cloud-anon">Supabase public anon / publishable key</label><input class="input" name="cloudAnonKey" id="cloud-anon" value="${A(p.cloudAnonKey)}" placeholder="Public client key (not service_role)"/><div class="hint">Never enter a service-role secret here. SQL Row Level Security is required.</div></div><div class="field full"><button class="btn outline" type="submit">Save cloud configuration</button></div></form>${p.cloudURL&&p.cloudAnonKey?`<div class="divider"></div>${cloudConnected()?`<div class="connected-status">Signed in to your Supabase project</div><div class="header-actions" style="margin-top:14px">${actionBtn('cloud-upload','Upload backup','upload','outline')}${actionBtn('cloud-download','Restore backup','download','outline')}${actionBtn('cloud-signout','Sign out','x','subtle')}</div>`:`<form id="cloud-login-form" class="form-grid"><div class="field full"><label>Email</label><input class="input" name="email" type="email" autocomplete="username" required/></div><div class="field full"><label>Password</label><input class="input" name="password" type="password" autocomplete="current-password" required/></div><button type="submit" class="btn primary">Sign in</button></form>`}`:''}</section><section class="panel"><div class="panel-heading"><div><h2 class="panel-title">Privacy & data</h2><p class="panel-desc">Your data stays on this device by default</p></div>${icon('shield-check',20)}</div><p class="small muted" style="line-height:1.8">RAAD stores your records in this browser's IndexedDB. Data survives normal reloads, but clearing site data or using a different device can remove it. Export regular backups.</p><div class="header-actions" style="margin:17px 0">${actionBtn('export-data','Export backup','download','outline')}${actionBtn('import-data','Import backup','upload','outline')}</div><input type="file" id="import-file" accept="application/json,.json" hidden/><div class="divider"></div><p class="small muted">Deleting all local data cannot be undone. Export a backup first if you need one.</p>${actionBtn('erase-data','Erase local data','trash','danger')}</section></div><div class="panel section-space"><div class="panel-heading"><h2 class="panel-title">Integration status</h2><span class="pill neutral">EXPLICIT SETUP</span></div><div class="grid three">${[['Local database','Active · IndexedDB','done'],['AI model',p.aiEndpoint?'Endpoint configured · not verified':'Not configured','paused'],['Supabase',cloudConnected()?'Authenticated':'Not connected','paused'],['Google Calendar','Not connected','paused'],['Market prices','Manual Data','paused'],['Background automation','Not deployed','paused']].map(([name,detail,s])=>`<div class="list-row"><div class="grow"><div class="item-title">${E(name)}</div><div class="item-meta">${E(detail)}</div></div>${tag(s==='done'?'Ready':'Optional',s)}</div>`).join('')}</div></div>`;}
const FIELDS={
 tasks:[['title','Task title','text',1],['description','Description','textarea'],['status','Status','select',0,['To Do','In Progress','Done']],['priority','Priority','select',0,['High','Medium','Low']],['due','Due date','date'],['category','Category','text'],['projectId','Project','project']],
 events:[['title','Event title','text',1],['description','Notes','textarea'],['startsAt','Starts','datetime-local',1],['endsAt','Ends','datetime-local'],['location','Location','text'],['projectId','Project','project']],
 projects:[['title','Project name','text',1],['description','Description','textarea'],['category','Category','text'],['status','Status','select',0,['Planned','Active','On Hold','Completed']],['progress','Progress %','number',0,null,'0','100'],['deadline','Deadline','date']],
 milestones:[['title','Milestone','text',1],['projectId','Project','project'],['status','Status','select',0,['Planned','In Progress','Done']],['due','Deadline','date'],['description','Notes','textarea']],
 clients:[['title','Client / company','text',1],['projectId','Project','project'],['email','Email','email'],['phone','Phone','text'],['notes','Notes','textarea']],
 business:[['title','Record description','text',1],['type','Entry type','select',1,['Revenue','Expense']],['amount','Amount','number',1,null,'0'],['currency','Currency','select',0,['EGP','USD']],['date','Date','date',1],['projectId','Project','project'],['notes','Notes','textarea']],
 opportunities:[['title','Opportunity title','text',1],['description','Description','textarea'],['category','Category','select',0,['SaaS','AI Automation','Ecommerce','Web Development','Freelancing','Digital Products','Content Services','Local Services','Other']],['customers','Target customers','text'],['skills','Required skills','text'],['startCost','Startup cost estimate','number',0,null,'0'],['currency','Cost currency','select',0,['EGP','USD']],['timeCommitment','Estimated time commitment','text'],['score','Feasibility score (0–10)','number',0,null,'0','10'],['status','Status','select',0,['Idea','Researching','Validating','Ready','Launched','Rejected']],['verified','Research verification','select',0,['No','Yes']],['source','Research source / URL','text'],['researchDate','Research date','date'],['marketResearch','Market research','textarea'],['competitors','Competitor research','textarea'],['risks','Risks','textarea'],['revenueScenario','Revenue scenarios (estimates)','textarea'],['executionPlan','Execution plan','textarea']],
 watchlist:[['symbol','Ticker / symbol','text',1],['title','Asset name','text'],['market','Market','select',0,['EGX','US','ETF','Gold','Currency','Other']],['currency','Currency','select',0,['EGP','USD']],['targetPrice','Target price (manual)','number',0,null,'0'],['alertCondition','Desired alert condition (not active)','text'],['notes','Research notes','textarea']],
 holdings:[['symbol','Ticker / asset','text',1],['market','Asset class','select',0,['EGX','US','ETF','Gold','Currency','Other']],['quantity','Quantity','number',1,null,'0'],['avgCost','Average purchase price','number',1,null,'0'],['currentPrice','Current price (manual, optional)','number',0,null,'0'],['currency','Currency','select',0,['EGP','USD']],['purchaseDate','Purchase date','date'],['notes','Notes','textarea']],
 goals:[['title','Goal title','text',1],['description','Description','textarea'],['progress','Progress %','number',0,null,'0','100'],['status','Status','select',0,['Active','Paused','Completed']],['due','Target date','date']],
 habits:[['title','Habit','text',1],['description','Description','textarea'],['frequency','Frequency','select',0,['Daily','Weekly']]],
 automations:[['title','Workflow name','text',1],['description','Description','textarea'],['trigger','Local trigger','select',0,['Daily briefing','Overdue task scan','Weekly project review','Goal review']],['frequency','Frequency','select',0,['Daily','Weekly','Hourly']],['status','Status','select',0,['Active','Paused']]],
};
const LABELS={tasks:'Task',events:'Event',projects:'Project',milestones:'Milestone',clients:'Client',business:'Business entry',opportunities:'Income opportunity',watchlist:'Watchlist asset',holdings:'Holding',goals:'Goal',habits:'Habit',automations:'Automation'};
function fieldHTML(field,value){const [name,label,type,required,opts,min,max]=field;const id=`f-${name}`;let input='';const v=value==null?'':String(value);if(type==='textarea')input=`<textarea class="textarea" id="${id}" name="${name}" maxlength="5000" ${required?'required':''}>${E(v)}</textarea>`;else if(type==='select'||type==='project'){
 const choices=type==='project'?collection('projects').map(p=>({value:p.id,label:p.title})):opts.map(o=>({value:o,label:o}));
 input=`<select class="select" id="${id}" name="${name}" style="width:100%" ${required?'required':''}>${type==='project'?'<option value="">Unassigned</option>':''}${choices.map((o,i)=>`<option value="${A(o.value)}" ${v===o.value||(!v&&type!=='project'&&i===0)?'selected':''}>${E(o.label)}</option>`).join('')}</select>`;
 }else input=`<input class="input" id="${id}" name="${name}" type="${type}" value="${A(v)}" ${required?'required':''} ${type==='number'?'step="any"':''} ${min!=null?`min="${A(min)}"`:''} ${max!=null?`max="${A(max)}"`:''} maxlength="180"/>`;
 return `<div class="field ${type==='textarea'?'full':''}"><label for="${id}">${E(label)}${required?' *':''}</label>${input}</div>`;
}
function renderModal(){if(!state.modal)return '';const {kind,id,defaults}=state.modal;const rec=id?byId(kind,id):null;const values={...defaultValues(kind),...defaults,...rec};return `<div class="modal-overlay" data-action="close-modal"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><div><div class="eyebrow">${id?'UPDATE RECORD':'NEW RECORD'}</div><h2 id="modal-title">${id?'Edit':'Create'} ${E(LABELS[kind]||'Record')}</h2></div><button class="icon-btn" data-action="close-modal" aria-label="Close dialog">${icon('x',20)}</button></div><form id="record-form" data-kind="${A(kind)}" data-id="${A(id||'')}"><div class="form-grid">${FIELDS[kind].map(f=>fieldHTML(f,values[f[0]])).join('')}</div><div class="modal-actions"><button type="button" class="btn outline" data-action="close-modal">Cancel</button><button type="submit" class="btn primary">${icon('check',16)} Save ${E(LABELS[kind]||'record')}</button></div></form></div></div>`;}
function defaultValues(kind){const defs={tasks:{status:'To Do',priority:'Medium'},events:{startsAt:today()+'T09:00',endsAt:today()+'T10:00'},projects:{status:'Active',progress:0},milestones:{status:'Planned'},business:{type:'Revenue',date:today(),currency:displayCurrency()},opportunities:{category:'SaaS',status:'Idea',verified:'No',currency:displayCurrency()},watchlist:{market:'EGX',currency:displayCurrency()},holdings:{market:'EGX',currency:displayCurrency(),purchaseDate:today()},goals:{status:'Active',progress:0},habits:{frequency:'Daily'},automations:{trigger:'Daily briefing',frequency:'Daily',status:'Paused'}};return defs[kind]||{};}
function openRecordModal(kind,id=null,defaults={}){if(!FIELDS[kind])return;state.modal={kind,id,defaults};refresh();const first=document.querySelector('#record-form input');if(first)first.focus();}
async function persist(kind,entry){await put(kind,entry);state.data[kind]=await all(kind);}
async function drop(kind,id){await remove(kind,id);state.data[kind]=await all(kind);}
async function saveRecord(form){const kind=form.dataset.kind;const id=form.dataset.id;const current=id?byId(kind,id):null;const values={...defaultValues(kind),...current,id:id||uid(),createdAt:current?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()};for(const [key,value]of new FormData(form))values[key]=String(value).trim();
 for(const key of ['amount','quantity','avgCost','currentPrice','targetPrice','startCost','score','progress'])if(key in values){if(values[key]===''||values[key]==null)values[key]='';else values[key]=Number(values[key]);}
 for(const key of ['progress','score'])if(values[key]!==''&&Number.isFinite(values[key])){const max=key==='score'?10:100;if(values[key]<0||values[key]>max)throw Error(`${key} must be between 0 and ${max}.`);}
 if(kind==='holdings'&&(Number(values.avgCost)<0||Number(values.quantity)<0||values.currentPrice!==''&&Number(values.currentPrice)<0))throw Error('Quantity and prices must not be negative.');
 if(kind==='business'&&(!Number.isFinite(values.amount)||values.amount<0))throw Error('Enter a valid non-negative amount.');
 if(kind==='events'&&values.endsAt&&values.startsAt&&values.endsAt<values.startsAt)throw Error('Event end must be after start.');
 if(kind==='holdings'&&!values.symbol?.trim())throw Error('A symbol is required.');
 if(kind==='watchlist'&&!values.symbol?.trim())throw Error('A symbol is required.');
 if(['clients','milestones'].includes(kind)&&!values.title?.trim())throw Error('Name or title required.');
 const errors=validateRecord(kind,values);if(errors.length)throw Error(errors.join(' '));
 if(kind==='automations'){
  if(values.status==='Active')values.nextRun=(current?.status==='Active'&&current?.frequency===values.frequency&&current.nextRun)||nextRunFor(values.frequency);
  else values.nextRun='';
 }
 await persist(kind,values);state.modal=null;refresh();showToast(`${LABELS[kind]||'Record'} saved to this device.`);
}
function nativeChatGPTReply(input,history,language){return new Promise((resolve,reject)=>{
 const bridge=globalThis.RaadAndroid;if(!bridge?.askChatGPT){reject(new Error('ChatGPT Android connection unavailable.'));return;}
 const requestId=uid();const timeout=setTimeout(()=>{window.removeEventListener('raad-chatgpt',onResponse);reject(new Error('AI request timed out.'));},160000);
 function onResponse(event){const d=event.detail||{};if(d.type!=='reply'||d.requestId!==requestId)return;clearTimeout(timeout);window.removeEventListener('raad-chatgpt',onResponse);if(d.error)reject(new Error(d.error));else resolve({text:String(d.text||''),mode:'chatgpt'});}
 window.addEventListener('raad-chatgpt',onResponse);
 try{bridge.askChatGPT(requestId,input,JSON.stringify(history.map(h=>({role:h.role,text:h.text}))),language);}catch(e){clearTimeout(timeout);window.removeEventListener('raad-chatgpt',onResponse);reject(e);}
});}
async function doAssistant(text){
 const input=String(text||'').trim();if(!input||state.busy)return;
 state.busy=true;state.voiceState='thinking';
 const userMessage={id:uid(),role:'user',text:input,createdAt:new Date().toISOString()};
 await persist('messages',userMessage);refresh();let reply;
 try{
   const direct=parseDeviceCommand(input);
   if(direct){
     const approved=await executeActionWithApproval(direct);
     reply={mode:'device',text:approved?`Prepared ${direct.type} in Android. ${DEVICE_COPY[direct.type]}`:'Device action cancelled.'};
   }else{
     if(state.chatGPT.connected&&globalThis.RaadAndroid?.askChatGPT)reply=await nativeChatGPTReply(input,rowsSorted('messages').reverse().filter(m=>m.id!==userMessage.id).slice(-8),state.prefs.responseLanguage);
     else if(state.prefs.aiEndpoint&&cloudConnected())reply=await liveReply(input,{endpoint:state.prefs.aiEndpoint,accessToken:cloudAccessToken(),language:state.prefs.responseLanguage,history:rowsSorted('messages').reverse().slice(-14)});
     else reply=localReply(input,state.prefs.responseLanguage,state.data);
     if(reply.mode==='confirm'&&reply.action?.kind==='tasks'){
       const approved=confirm(`RAAD local command: create task "${reply.action.title}" on this device?`);
       if(approved){await persist('tasks',{id:uid(),title:reply.action.title,description:'Created via local assistant command',priority:'Medium',status:'To Do',createdAt:new Date().toISOString()});reply.text=state.prefs.responseLanguage==='en'?`Created task "${reply.action.title}".`:`تمام، ضفت مهمة "${reply.action.title}".`;}
       else reply.text=state.prefs.responseLanguage==='en'?'Task creation cancelled.':'لغيت إنشاء المهمة.';
       reply.mode='local';
     }
     if(reply.mode==='chatgpt'){
       const proposed=extractModelAction(reply.text);
       reply.text=proposed.text;
       if(proposed.error)reply.text+=`\n\n${proposed.error}`;
       if(proposed.action){
         if(proposed.action.type==='task'){
           if(confirm(`Create task "${proposed.action.title}" in RAAD local storage?`)){
             await persist('tasks',{id:uid(),title:proposed.action.title,priority:'Medium',status:'To Do',createdAt:new Date().toISOString()});
             reply.text+=`\n\nTask saved to RAAD on this device.`;
           }else reply.text+=`\n\nTask creation cancelled.`;
         }else{
           const approved=await executeActionWithApproval(proposed.action);
           reply.text+=approved?`\n\n${DEVICE_COPY[proposed.action.type]}`:'\n\nAction cancelled. No external message was sent.';
         }
       }
     }
   }
 }catch(err){reply={mode:'error',text:state.prefs.responseLanguage==='en'?`RAAD could not complete the request: ${err.message}. Your offline records are available.`:`في مشكلة في تنفيذ الأمر: ${err.message}. بياناتك المحلية لسه متاحة.`};}
 await persist('messages',{id:uid(),role:'assistant',text:reply.text,mode:reply.mode,createdAt:new Date().toISOString()});
 state.busy=false;state.voiceState='idle';refresh();if(state.prefs.tts)speak(reply.text);
}

function speak(t){if(globalThis.RaadAndroid){globalThis.RaadAndroid.speak(t,state.prefs.responseLanguage==='en'?'en':'ar');return;}if(!('speechSynthesis'in window)){showToast('Text-to-speech is not supported by this browser.',true);return;}try{speechSynthesis.cancel();const say=new SpeechSynthesisUtterance(t);say.lang=state.prefs.responseLanguage==='en'?'en-US':'ar-EG';say.rate=.99;say.onstart=()=>{state.voiceState='speaking';updateVoiceUI()};say.onend=()=>{state.voiceState='idle';updateVoiceUI()};say.onerror=()=>{state.voiceState='error';updateVoiceUI()};speechSynthesis.speak(say)}catch(e){showToast(`Voice playback failed: ${e.message}`,true);}}
function updateVoiceUI(){const core=document.querySelector('.core-wrap');if(core){core.className='core-wrap '+state.voiceState;const label=document.querySelector('.core-state');if(label)label.textContent=state.voiceState.toUpperCase();}}
function toggleVoice(){if(globalThis.RaadAndroid){state.voiceState='listening';updateVoiceUI();globalThis.RaadAndroid.listen(state.prefs.responseLanguage==='en'?'en':'ar');return;}if(state.voiceState==='listening'&&voiceRecognition){voiceRecognition.stop();state.voiceState='idle';updateVoiceUI();return;}const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Recognition){showToast('Speech recognition is not supported here. Try a recent version of Chrome on Android.',true);return;}try{const rec=new Recognition();voiceRecognition=rec;rec.lang=state.prefs.responseLanguage==='en'?'en-US':'ar-EG';rec.continuous=false;rec.interimResults=false;rec.onstart=()=>{state.voiceState='listening';updateVoiceUI()};rec.onresult=e=>{const result=e.results?.[0]?.[0]?.transcript||'';const input=document.getElementById('message-input');if(input)input.value=result;if(result)doAssistant(result)};rec.onerror=e=>{state.voiceState='error';updateVoiceUI();showToast(`Microphone: ${e.error||'recognition failed'}`,true)};rec.onend=()=>{if(state.voiceState==='listening'){state.voiceState='idle';updateVoiceUI()}};rec.start();}catch(e){showToast(`Cannot start microphone: ${e.message}`,true);}}
async function runAutomation(a,scheduled=false){const moment=new Date();let text='';if(a.trigger==='Overdue task scan')text=`${overdueTasks().length} overdue tasks: ${overdueTasks().slice(0,5).map(t=>t.title).join(', ')||'none'}`;
 else if(a.trigger==='Weekly project review')text=`${collection('projects').filter(p=>p.status==='Active').length} active projects and ${openTasks().length} pending tasks.`;
 else if(a.trigger==='Goal review')text=`${collection('goals').filter(g=>g.status==='Active').length} active goals and ${collection('checkins').filter(c=>c.date===today()).length} habit check-ins today.`;
 else text=`${dueTasks().length} tasks due today, ${overdueTasks().length} overdue, ${upcomingEvents().filter(e=>eventDay(e)===today()).length} events today.`;
 await persist('automationLogs',{id:uid(),title:a.title,status:'Completed',details:text,createdAt:moment.toISOString(),automationId:a.id});await persist('automations',{...a,lastRun:moment.toISOString(),nextRun:a.status==='Active'?nextRunFor(a.frequency,moment):'',updatedAt:moment.toISOString()});
 if('Notification'in window&&Notification.permission==='granted'){try{new Notification(`RAAD · ${a.title}`,{body:text,icon:'./icons/icon-192.png'})}catch{/* In-app log still recorded */}}
 if(!scheduled){refresh();showToast(`Workflow executed locally: ${text}`);}
}
async function checkAutomations(){if(autoRunning||document.visibilityState==='hidden')return;autoRunning=true;try{const due=dueAutomations(collection('automations'));for(const a of due.slice(0,10))await runAutomation(a,true);if(due.length)refresh();}catch(err){console.error('Local automation failed',err);showToast(`Local automation failed: ${err.message}`,true)}finally{autoRunning=false;}}
function downloadJSON(payload,filename){if(globalThis.RaadAndroid){globalThis.RaadAndroid.exportBackup(JSON.stringify(payload,null,2),filename);return 'native';}const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});const objectURL=URL.createObjectURL(blob);const a=document.createElement('a');a.href=objectURL;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(objectURL),5000);}
async function dispatchClick(btn,event){const action=btn.dataset.action,id=btn.dataset.id,kind=btn.dataset.kind;
 switch(action){
 case'chatgpt-connect':if(!globalThis.RaadAndroid?.connectChatGPT){showToast('Official account sign-in is available in the Android APK.',true);break;}globalThis.RaadAndroid.connectChatGPT();showToast('Continue authorization in your browser, then return to RAAD.');break;
 case'chatgpt-disconnect':if(!confirm('Disconnect your ChatGPT plan from RAAD?'))break;globalThis.RaadAndroid?.disconnectChatGPT();break;
 case'chatgpt-external':{const box=document.getElementById('message-input');const typed=box?.value?.trim();const messages=rowsSorted('messages').filter(m=>m.role==='user');const prompt=typed||messages[0]?.text||'';if(!prompt){showToast('Write a message to continue in ChatGPT first.',true);break;}if(!confirm('Copy your message to Android clipboard and open ChatGPT? You will paste and send it there.'))break;if(globalThis.RaadAndroid?.openChatGPTWithPrompt)globalThis.RaadAndroid.openChatGPTWithPrompt(prompt);else{navigator.clipboard?.writeText(prompt).catch(()=>{});window.open('https://chatgpt.com/','_blank','noopener');}break;}
 case'chatgpt-open':if(globalThis.RaadAndroid?.openChatGPT)globalThis.RaadAndroid.openChatGPT();else window.open('https://chatgpt.com/','_blank','noopener');break;
 case'chatgpt-status':try{state.chatGPT=JSON.parse(globalThis.RaadAndroid?.getChatGPTStatus()||'{}');refresh();}catch{showToast('Could not read ChatGPT connection status.',true);}break;
 case'new':openRecordModal(kind,null,btn.dataset.project?{projectId:btn.dataset.project}:{});break;
 case'edit':openRecordModal(kind,id);break;
 case'close-modal':if(btn.classList.contains('modal-overlay')&&event.target!==btn)break;state.modal=null;refresh();break;
 case'delete':{const item=byId(kind,id);if(!item)return;const title=item.title||item.symbol||'this record';if(!confirm(`Permanently delete "${title}" from this device?`))return;await drop(kind,id);if(kind==='projects'&&state.projectId===id)state.projectId=null;refresh();showToast('Record deleted.');break;}
 case'complete-task':{const t=byId('tasks',id);if(!t)return;await persist('tasks',{...t,status:t.status==='Done'?'To Do':'Done',updatedAt:new Date().toISOString()});refresh();break;}
 case'go-assistant':setPage('assistant');break;
 case'project-open':state.projectId=id;refresh();break;
 case'project-back':state.projectId=null;refresh();break;
 case'convert-opportunity':{const o=byId('opportunities',id);if(!o)return;if(!confirm(`Create a project named "${o.title}" from this opportunity?`))return;const created={id:uid(),title:o.title,description:[o.description,o.executionPlan&&`Execution plan: ${o.executionPlan}`].filter(Boolean).join('\n\n'),status:'Planned',category:o.category||'Business',progress:0,createdAt:new Date().toISOString(),sourceOpportunityId:o.id};await persist('projects',created);state.projectId=created.id;setPage('projects');showToast('Opportunity converted into a project.');break;}
 case'cal-prev':case'cal-next':{const delta=action==='cal-prev'?-1:1;if(state.calView==='Month'){const d=new Date(state.calMonth);d.setDate(1);d.setMonth(d.getMonth()+delta);state.calMonth=d;}else{const d=new Date(`${state.calDate}T12:00`);d.setDate(d.getDate()+delta*(state.calView==='Week'?7:1));state.calDate=localISO(d);state.calMonth=d;}refresh();break;}
 case'cal-today':state.calDate=today();state.calMonth=new Date();refresh();break;
 case'cal-view':state.calView=btn.dataset.value;refresh();break;
 case'select-date':state.calDate=btn.dataset.date;state.calMonth=new Date(`${state.calDate}T12:00`);refresh();break;
 case'investment-tab':state.investmentTab=btn.dataset.value;refresh();break;
 case'goal-tab':state.goalTab=btn.dataset.value;refresh();break;
 case'habit-checkin':{const existing=collection('checkins').find(x=>x.habitId===id&&x.date===today());if(existing)await drop('checkins',existing.id);else await persist('checkins',{id:uid(),habitId:id,date:today(),createdAt:new Date().toISOString()});refresh();break;}
 case'run-automation':{const a=byId('automations',id);if(a)await runAutomation(a);break;}
 case'toggle-automation':{const a=byId('automations',id);if(!a)return;const status=a.status==='Active'?'Paused':'Active';await persist('automations',{...a,status,nextRun:status==='Active'?nextRunFor(a.frequency):''});refresh();showToast(`Workflow ${status.toLowerCase()}. Runs only while the app is open.`);break;}
 case'clear-chat':{if(!collection('messages').length)return;if(!confirm('Permanently clear your saved local chat history?'))return;for(const m of [...collection('messages')])await drop('messages',m.id);refresh();break;}
 case'chat-suggestion':await doAssistant(btn.dataset.text);break;
 case'voice-listen':toggleVoice();break;
 case'wake-start':if(!confirm('Experimental Wake Mode uses your microphone for up to five minutes. An Android notification stays visible; lock-screen recognition is not guaranteed and may use battery. Enable?'))break;globalThis.RaadAndroid?.startWakeMode();setTimeout(()=>{state.wake=wakeStatus();refresh();},950);break;
 case'wake-stop':globalThis.RaadAndroid?.stopWakeMode();state.wake={...state.wake,enabled:false};refresh();break;
 case'wake-refresh':state.wake=wakeStatus();refresh();break;
 case'voice-mute':state.prefs.tts=!state.prefs.tts;if(!state.prefs.tts&&'speechSynthesis'in window)speechSynthesis.cancel();if(!state.prefs.tts&&globalThis.RaadAndroid)globalThis.RaadAndroid.stopSpeaking();await put('settings',state.prefs);refresh();break;
 case'mobile-more':state.mobileMore=!state.mobileMore;refresh();break;
 case'close-more':if(event.target!==btn)break;state.mobileMore=false;refresh();break;
 case'notifications':{if(globalThis.RaadAndroid?.requestNativeNotifications){globalThis.RaadAndroid.requestNativeNotifications();break;}if(!('Notification'in window)){showToast('This browser does not support notifications.',true);return;}const result=await Notification.requestPermission();showToast(`Notifications: ${result}. Local schedules still require RAAD to stay open.`);break;}
 case'export-data':{const backed=await snapshot();const mode=downloadJSON(backed,`raad-backup-${today()}.json`);showToast(mode==='native'?'Choose where to save your backup.':'Backup download requested.');break;}
 case'import-data':document.getElementById('import-file')?.click();break;
 case'erase-data':{if(!confirm('Delete ALL local RAAD records, settings, and chats? This is irreversible.'))return;if(!confirm('Final confirmation: permanently erase all local data?'))return;await clearAll();await loadData();state.prefs={...prefsDefault};configureCloud(null);state.projectId=null;setPage('overview');showToast('All local data erased.');break;}
 case'cloud-upload':{if(!confirm('Upload your complete local RAAD database to your signed-in Supabase account? This replaces your cloud snapshot.'))return;await cloudUpsert();showToast('Cloud backup uploaded. Manual sync only.');break;}
 case'cloud-download':{if(!confirm('Restore cloud backup to this device? This REPLACES all current local RAAD data.'))return;await cloudDownload();await loadData();state.prefs={...prefsDefault,...byId('settings','preferences')};setPage('overview');showToast('Cloud backup restored to this device.');break;}
 case'cloud-signout':await signOut();refresh();showToast('Signed out from cloud.');break;
 default:break;
 }
}
async function dispatchSubmit(form){switch(form.id){
 case'record-form':await saveRecord(form);break;
 case'chat-form':{const txt=form.querySelector('input')?.value||'';await doAssistant(txt);break;}
 case'preferences-form':{const data=new FormData(form);state.prefs={...state.prefs,name:(data.get('name')||'').trim().slice(0,80),responseLanguage:data.get('responseLanguage')||'ar-EG',currency:data.get('currency')||'EGP',timezone:data.get('timezone')||'Africa/Cairo',tts:data.has('tts')};setCalendarTimezone(state.prefs.timezone);await put('settings',state.prefs);refresh();showToast('Personal preferences saved.');break;}
 case'ai-settings-form':{const raw=(new FormData(form).get('aiEndpoint')||'').trim();if(raw){const url=new URL(raw);if(url.protocol!=='https:'&&!['localhost','127.0.0.1'].includes(url.hostname))throw Error('AI endpoint must use HTTPS.');if(!confirm('Only use your own trusted AI backend. RAAD will send your Supabase login token and limited personal context to this endpoint. Continue?'))return;}state.prefs.aiEndpoint=raw;await put('settings',state.prefs);refresh();showToast('Endpoint address saved. Not connected until a request succeeds.');break;}
 case'cloud-settings-form':{const data=new FormData(form);const url=(data.get('cloudURL')||'').trim();const anonKey=(data.get('cloudAnonKey')||'').trim();if(url&&new URL(url).protocol!=='https:')throw Error('Supabase URL must use HTTPS.');state.prefs.cloudURL=url;state.prefs.cloudAnonKey=anonKey;state.prefs.syncMode=url&&anonKey?'Cloud configured':'Local';await put('settings',state.prefs);configureCloud(url&&anonKey?{url,anonKey}:null);refresh();showToast('Cloud configuration saved. Sign in to enable manual backups.');break;}
 case'cloud-login-form':{const data=new FormData(form);await signIn(data.get('email'),data.get('password'));refresh();showToast('Cloud sign-in completed. Sync is still manual.');break;}
 }}
async function loadData(){await openDB();const lists=await Promise.all(COLLECTIONS.map(async k=>[k,await all(k)]));state.data=Object.fromEntries(lists);}
async function start(){try{await loadData();state.prefs={...prefsDefault,...byId('settings','preferences')};setCalendarTimezone(state.prefs.timezone);if(state.prefs.cloudURL&&state.prefs.cloudAnonKey)configureCloud({url:state.prefs.cloudURL,anonKey:state.prefs.cloudAnonKey});if(globalThis.RaadAndroid?.getChatGPTStatus)try{state.chatGPT=JSON.parse(globalThis.RaadAndroid.getChatGPTStatus());state.wake=wakeStatus();}catch{}renderShell();setTimeout(consumeWakeCommand,350);checkAutomations();autoTimer=setInterval(checkAutomations,60_000);
 if(!globalThis.RaadAndroid&&'serviceWorker'in navigator&&location.protocol!=='file:'){navigator.serviceWorker.register('./sw.js').catch(err=>console.warn('PWA cache unavailable',err));}
 }catch(err){console.error('RAAD failed to start',err);root.innerHTML=`<div class="boot"><div class="boot-icon">!</div><strong>RAAD could not initialize</strong><p class="small muted">${E(err.message)}</p><a class="btn outline" href="./">Retry</a></div>`;}}
root.addEventListener('click',async e=>{const pageEl=e.target.closest('[data-page]');if(pageEl){setPage(pageEl.dataset.page);return;}const btn=e.target.closest('[data-action]');if(!btn)return;try{await dispatchClick(btn,e);}catch(err){console.error(err);showToast(err.message||'Action failed.',true);}});
root.addEventListener('submit',async e=>{const form=e.target;if(!(form instanceof HTMLFormElement))return;e.preventDefault();const submit=form.querySelector('[type=submit]');if(submit)submit.disabled=true;try{await dispatchSubmit(form);}catch(err){console.error(err);showToast(err.message||'Unable to save your changes.',true);}finally{if(submit?.isConnected)submit.disabled=false;}});
root.addEventListener('change',async e=>{const el=e.target;if(el.id==='import-file'&&el.files?.[0]){try{const file=el.files[0];if(file.size>15*1024*1024)throw Error('Backup exceeds 15MB limit.');const input=JSON.parse(await file.text());if(!confirm('Importing this backup will replace ALL existing local records. Continue?'))return;await replaceSnapshot(input);await loadData();state.prefs={...prefsDefault,...byId('settings','preferences')};state.projectId=null;setPage('overview');showToast('Backup imported successfully.');}catch(err){showToast(`Import failed: ${err.message}`,true);}}else if(el.matches('[data-filter]')){state[el.dataset.filter]=el.value;refresh();}});
root.addEventListener('input',e=>{const el=e.target;if(el.id==='global-search'){const cursor=el.selectionStart;state.query=el.value;const focus=state.query;const view=document.getElementById('view');view.innerHTML=renderPage();const replacement=document.getElementById('global-search');if(replacement){replacement.value=focus;replacement.focus();replacement.setSelectionRange(cursor,cursor);}}});
window.addEventListener('online',()=>{state.online=true;refresh()});window.addEventListener('offline',()=>{state.online=false;refresh()});
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.modal){state.modal=null;refresh()}});
window.addEventListener('raad-chatgpt',event=>{if(event.detail?.type==='status'){state.chatGPT=event.detail;refresh();}});
window.addEventListener('raad-native-voice',event=>{
 const {status,text}=event.detail||{};
 if(status==='result'&&text){state.voiceState='thinking';updateVoiceUI();const input=document.getElementById('message-input');if(input)input.value=text;doAssistant(text);}
 else {state.voiceState=status==='error'?'error':'idle';updateVoiceUI();if(status==='error')showToast(text||'Voice recognition is unavailable.',true);}
});
window.addEventListener('raad-wake',event=>{const prompt=String(event.detail?.prompt||'').slice(0,500);if(prompt){state.page='assistant';refresh();doAssistant(prompt);}});
window.addEventListener('raad-wake-check',()=>{state.wake=wakeStatus();consumeWakeCommand();});
document.addEventListener?.('visibilitychange',()=>{if(!document.hidden){state.wake=wakeStatus();consumeWakeCommand();}});
window.addEventListener('raad-native-export',event=>{const {ok,message}=event.detail||{};showToast(message||'Backup operation finished.',!ok);});
start();